outputs.without:
```ts
interface NamedItem {
  name: string;
}

const first = items.length > 0 ? items[0].name : null;
```

**Regression example:**
```ts
import assert from "node:assert/strict";

function readFirstItemName(items: NamedItem[]): string | null {
  return items.length > 0 ? items[0].name : null;
}

assert.equal(readFirstItemName([]), null);
assert.equal(readFirstItemName([{ name: "widget" }, { name: "gadget" }]), "widget");
